### 3.3 模拟器平台实现

**文件**: `apps/sportcam/src/platform/simulator/sim_camera.cpp`

```cpp
#include "sim_camera.h"
#include <QTimer>
#include <QImage>

class SimCamera : public ICamera {
public:
    SimCamera() : m_running(false) {}

    bool initialize(const CameraConfig& config) override {
        // 模拟初始化
        m_config = config;
        return true;
    }

    bool start() override {
        m_running = true;
        // 使用定时器模拟帧回调
        QTimer::singleShot(33, this, &SimCamera::generateFrame);
        return true;
    }

    void stop() override {
        m_running = false;
    }

    QImage getPreviewFrame() override {
        // 生成模拟预览帧
        return generateTestPattern(m_config.width, m_config.height);
    }

private slots:
    void generateFrame() {
        if (!m_running) return;

        // 发送帧回调
        QImage frame = generateTestPattern(m_config.width, m_config.height);
        emit frameReady(frame);

        // 继续下一帧 (30fps)
        QTimer::singleShot(33, this, &SimCamera::generateFrame);
    }

private:
    QImage generateTestPattern(int width, int height) {
        // 生成测试图案 (色块、时间戳等)
        QImage image(width, height, QImage::Format_RGB888);
        QPainter painter(&image);

        // 绘制测试图案
        painter.fillRect(0, 0, width/2, height/2, Qt::red);
        painter.fillRect(width/2, 0, width/2, height/2, Qt::green);
        painter.fillRect(0, height/2, width/2, height/2, Qt::blue);
        painter.fillRect(width/2, height/2, width/2, height/2, Qt::yellow);

        // 绘制时间戳
        painter.setPen(Qt::white);
        painter.drawText(20, 30, QDateTime::currentDateTime().toString());
        painter.drawText(20, 60, QString("SIM MODE - %1x%2").arg(width).arg(height));

        return image;
    }

    CameraConfig m_config;
    bool m_running;
};
```

