### 4.3 升级流程

```
┌─────────────────────────────────────────────────────────────────┐
│                      A/B OTA 升级流程                            │
├─────────────────────────────────────────────────────────────────┤
│                                                                  │
│  1. 检查当前活跃分区 (A 或 B)                                    │
│     ↓                                                            │
│  2. 下载 OTA 包到 misc-ab 分区                                  │
│     ↓                                                            │
│  3. 验证 OTA 包签名                                              │
│     ↓                                                            │
│  4. 写入非活跃分区 (如当前 A，则写入 B)                          │
│     ↓                                                            │
│  5. 设置非活跃分区优先级 higher                                  │
│     ↓                                                            │
│  6. 标记非活跃分区 tries_remaining = 3                          │
│     ↓                                                            │
│  7. 重启                                                         │
│     ↓                                                            │
│  8. Bootloader 检查优先级，从新分区启动                          │
│     ↓                                                            │
│  9. 系统运行正常?                                                │
│     ├─ 是 → 标记分区 successful = true, 完成                     │
│     └─ 否 → tries_remaining--, 回滚到旧分区                      │
│                                                                  │
└─────────────────────────────────────────────────────────────────┘
```

### 4.4 OTA Manager 实现

**文件**: `apps/sportcam/src/core/system/ota_manager.cpp`

```cpp
#include "ota_manager.h"
#include <QFile>
#include <QJsonDocument>
#include <QProcess>

class OTAManager : public IOTAManager {
public:
    OTAManager(QObject* parent = nullptr) : QObject(parent) {
        loadConfig();
    }

    bool checkUpdate(const QString& versionUrl) override {
        // 检查服务器可用更新
        QNetworkRequest request(versionUrl);
        QNetworkReply* reply = m_networkManager.get(request);

        connect(reply, &QNetworkReply::finished, [this, reply]() {
            if (reply->error() == QNetworkReply::NoError) {
                QJsonDocument doc = QJsonDocument::fromJson(reply->readAll());
                emit updateAvailable(doc.object());
            }
            reply->deleteLater();
        });

        return true;
    }

    bool downloadUpdate(const QString& otaUrl) override {
        // 下载 OTA 包到 misc-ab 分区
        QString outputPath = "/misc-ab/update.zip";

        QNetworkRequest request(otaUrl);
        QNetworkReply* reply = m_networkManager.get(request);

        connect(reply, &QNetworkReply::downloadProgress, 
                this, &OTAManager::downloadProgress);

        connect(reply, &QNetworkReply::finished, [this, reply, outputPath]() {
            if (reply->error() == QNetworkReply::NoError) {
                QFile file(outputPath);
                if (file.open(QIODevice::WriteOnly)) {
                    file.write(reply->readAll());
                    file.close();
                    emit downloadComplete(outputPath);
                }
            }
            reply->deleteLater();
        });

        return true;
    }

    bool verifyUpdate(const QString& packagePath) override {
        // 验证签名
        QProcess process;
        process.start("rkupdate", QStringList() << "--verify" << packagePath);
        process.waitForFinished();

        return process.exitCode() == 0;
    }

    bool applyUpdate(const QString& packagePath) override {
        // 确定非活跃分区
        QString currentSlot = getCurrentSlot();
        QString targetSlot = (currentSlot == "a") ? "b" : "a";

        // 使用 rkupdate 写入目标分区
        QProcess process;
        QStringList args;
        args << "--slot=" + targetSlot << "--package=" << packagePath;

        process.start("rkupdate", args);
        process.waitForFinished(-1); // 等待完成

        if (process.exitCode() == 0) {
            // 设置启动优先级
            setSlotPriority(targetSlot, 15);
            setSlotTriesRemaining(targetSlot, 3);

            // 请求重启
            emit rebootRequested();
            return true;
        }

        return false;
    }

    bool markBootSuccessful() override {
        QString currentSlot = getCurrentSlot();
        setSlotSuccessful(currentSlot, true);
        return true;
    }

private:
    QString getCurrentSlot() {
        // 从 misc-ab 读取当前 slot
        QFile file("/misc-ab/ota_state.json");
        if (file.open(QIODevice::ReadOnly)) {
            QJsonDocument doc = QJsonDocument::fromJson(file.readAll());
            return doc.object()["current_slot"].toString();
        }
        return "a";
    }

    void setSlotPriority(const QString& slot, int priority) {
        // 设置分区优先级
        QJsonObject config = loadConfig();
        config["priority"][slot] = priority;
        saveConfig(config);
    }

    QJsonObject loadConfig() {
        QFile file("/misc-ab/ota_config.json");
        if (file.open(QIODevice::ReadOnly)) {
            return QJsonDocument::fromJson(file.readAll()).object();
        }
        return QJsonObject();
    }

    QNetworkAccessManager m_networkManager;
};
```

### 4.5 创建 OTA 包脚本

**文件**: `scripts/ota/create_ota.sh`

```bash
#!/bin/bash
set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(dirname "$(dirname "$SCRIPT_DIR")")"
SDK_PATH="/home/lijian/project/rv1126b/atk/atk_dlrv1126b_linux6.1_sdk_release_v1.2.1_20260327"

VERSION=$1
OUTPUT_DIR="$PROJECT_ROOT/output/ota"
CURRENT_SLOT=${2:-a}

if [ -z "$VERSION" ]; then
    echo "Usage: $0 <version> [current_slot]"
    exit 1
fi

echo "Creating OTA package v$VERSION for slot transition from $CURRENT_SLOT..."

# 确定目标 slot
if [ "$CURRENT_SLOT" = "a" ]; then
    TARGET_SLOT="b"
else
    TARGET_SLOT="a"
fi

mkdir -p "$OUTPUT_DIR"

# 1. 构建新版本应用
"$SCRIPT_DIR/../build_cross.sh"

# 2. 创建新的 rootfs
cd "$PROJECT_ROOT/ubuntu_debian"
make all

# 3. 准备 OTA 包内容
OTA_WORKDIR="$OUTPUT_DIR/ota_work_$VERSION"
rm -rf "$OTA_WORKDIR"
mkdir -p "$OTA_WORKDIR"

# 复制新镜像
cp "$PROJECT_ROOT/ubuntu_debian/rootfs.ext4" "$OTA_WORKDIR/rootfs_${TARGET_SLOT}.img"
cp "$SDK_PATH/output/firmware/boot.img" "$OTA_WORKDIR/boot_${TARGET_SLOT}.img"

# 4. 创建 payload
cat > "$OTA_WORKDIR/payload.json" << EOF
{
  "version": "$VERSION",
  "target_slot": "$TARGET_SLOT",
  "images": {
    "boot": "boot_${TARGET_SLOT}.img",
    "rootfs": "rootfs_${TARGET_SLOT}.img"
  },
  "post_install": [
    "systemctl daemon-reload",
    "systemctl restart sportcam"
  ]
}
EOF

# 5. 打包并签名
cd "$OTA_WORKDIR"
zip -r "../ota_${VERSION}.zip" *
cd ..

# 6. 签名 (使用 rkupdate)
rkupdate --sign "ota_${VERSION}.zip" "ota_${VERSION}_signed.zip"

echo "OTA package created: $OUTPUT_DIR/ota_${VERSION}_signed.zip"
