PACKAGE_NAME="sportcam-app-${VERSION}"

echo "Packaging SportCam Application v${VERSION}..."

mkdir -p "$OUTPUT_DIR"

# 创建临时目录
WORKDIR=$(mktemp -d)
trap "rm -rf $WORKDIR" EXIT

# 创建包结构
mkdir -p "$WORKDIR/$PACKAGE_NAME"
cd "$WORKDIR/$PACKAGE_NAME"

# 复制构建产物
mkdir -p usr/bin usr/share/sportcam etc/sportcam

cp "$BUILD_DIR/sportcam" usr/bin/
cp -r "$PROJECT_ROOT/apps/sportcam/src/ui/qml" usr/share/sportcam/
cp -r "$PROJECT_ROOT/apps/sportcam/resources" usr/share/sportcam/
cp "$PROJECT_ROOT/apps/sportcam/config/"*.conf etc/sportcam/

# 创建安装脚本
cat > install.sh << 'EOF'
#!/bin/bash
set -e

echo "Installing SportCam Application..."

# 停止服务
systemctl stop sportcam || true

# 备份旧版本
if [ -f /usr/bin/sportcam ]; then
    cp /usr/bin/sportcam /usr/bin/sportcam.bak
fi

# 安装新文件
cp usr/bin/sportcam /usr/bin/
cp -r usr/share/sportcam/* /usr/share/sportcam/
cp etc/sportcam/*.conf /etc/sportcam/

# 设置权限
chmod +x /usr/bin/sportcam

# 重启服务
systemctl daemon-reload
systemctl start sportcam

echo "Installation complete!"
EOF

chmod +x install.sh

# 创建卸载脚本
cat > uninstall.sh << 'EOF'
