set -e

echo "Uninstalling SportCam Application..."

systemctl stop sportcam || true
systemctl disable sportcam || true

rm -f /usr/bin/sportcam
rm -rf /usr/share/sportcam
rm -f /etc/sportcam/*.conf

echo "Uninstallation complete!"
EOF

chmod +x uninstall.sh

# 创建控制文件
cat > control << EOF
Package: sportcam-app
Version: ${VERSION}
Architecture: arm64
Maintainer: SportCam Team
Description: SportCam Application for RV1126B
 Qt-based camera application with recording and
 streaming capabilities.
Depends: qt5base, qt5quick, qt5quickcontrols2, qt5multimedia, rockchip-mpp, rockchip-rga
EOF

# 打包
