### 6.2 主构建脚本

**文件**: `scripts/build.sh`

```bash
#!/bin/bash
set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(dirname "$SCRIPT_DIR")"

# 颜色输出
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
NC='\033[0m'

log_info() {
    echo -e "${GREEN}[INFO]${NC} $1"
}

log_warn() {
    echo -e "${YELLOW}[WARN]${NC} $1"
}

usage() {
    cat << EOF
Usage: $(basename "$0") [COMMAND] [OPTIONS]

Commands:
    sim         Build for PC simulator (default)
    cross       Build for RV1126B target
    app         Build application package
    system      Build full system firmware
    deploy      Deploy to device
    clean       Clean build artifacts
    help        Show this help

Options:
    -j N        Use N parallel jobs
    -v          Enable verbose output
    -d          Enable debug build

Examples:
    $(basename "$0") sim              # Build simulator
    $(basename "$0") cross -j8        # Cross-compile with 8 jobs
    $(basename "$0") app -d           # Build debug app package
    $(basename "$0") deploy           # Deploy to board

EOF
}

# 参数解析
BUILD_TYPE="sim"
JOBS=$(nproc)
VERBOSE=0
DEBUG=0

while [[ $# -gt 0 ]]; do
    case $1 in
        sim|cross|app|system|deploy|clean|help)
            BUILD_TYPE="$1"
            shift
            ;;
        -j)
            JOBS="$2"
            shift 2
            ;;
        -v)
            VERBOSE=1
            shift
            ;;
        -d)
            DEBUG=1
            shift
            ;;
        *)
            echo "Unknown option: $1"
            usage
            exit 1
            ;;
    esac
done

# 构建模拟器
build_simulator() {
    log_info "Building for PC Simulator..."

    BUILD_DIR="$PROJECT_ROOT/build-simulator"
    mkdir -p "$BUILD_DIR"

    cd "$BUILD_DIR"

    CMAKE_ARGS=(
        "-DCMAKE_TOOLCHAIN_FILE=$PROJECT_ROOT/cmake/toolchain/aarch64-sim-linux-gnu.cmake"
    )

    if [ $DEBUG -eq 1 ]; then
        CMAKE_ARGS+=("-DCMAKE_BUILD_TYPE=Debug")
        CMAKE_ARGS+=("-DENABLE_QT_DEBUG=ON")
    else
        CMAKE_ARGS+=("-DCMAKE_BUILD_TYPE=Release")
    fi

    cmake "${CMAKE_ARGS[@]}" "$PROJECT_ROOT/apps/sportcam"
    make -j"$JOBS"

    log_info "Simulator build complete: $BUILD_DIR/sportcam"
    log_info "Run with: $BUILD_DIR/sportcam"
}

# 交叉编译
build_cross() {
    log_info "Cross-compiling for RV1126B..."

    BUILD_DIR="$PROJECT_ROOT/build-target"
    mkdir -p "$BUILD_DIR"

    cd "$BUILD_DIR"

    CMAKE_ARGS=(
        "-DCMAKE_TOOLCHAIN_FILE=$PROJECT_ROOT/cmake/toolchain/aarch64-rockchip-linux-gnu.cmake"
        "-DBUILD_FOR_TARGET=ON"
    )

    if [ $DEBUG -eq 1 ]; then
        CMAKE_ARGS+=("-DCMAKE_BUILD_TYPE=Debug")
    else
        CMAKE_ARGS+=("-DCMAKE_BUILD_TYPE=Release")
    fi

    cmake "${CMAKE_ARGS[@]}" "$PROJECT_ROOT/apps/sportcam"
    make -j"$JOBS"

    log_info "Cross-compile complete: $BUILD_DIR/sportcam"
}

# 打包应用
build_app() {
    log_info "Building application package..."

    build_cross

    "$SCRIPT_DIR/package_app.sh"

    log_info "App package complete"
}

# 部署到板子
deploy_to_device() {
    log_info "Deploying to device..."

    DEVICE_IP="192.168.1.109"
    DEVICE_USER="rooter"

    # 检查连接
    if ! ping -c 1 -W 2 "$DEVICE_IP" &>/dev/null; then
        log_warn "Cannot reach device at $DEVICE_IP"
        exit 1
    fi

    # 传输应用包
    APP_PKG=$(ls -t "$PROJECT_ROOT/output/app"/sportcam-app-*.tar.gz 2>/dev/null | head -1)

    if [ -z "$APP_PKG" ]; then
        log_warn "No app package found. Building..."
        build_app
        APP_PKG=$(ls -t "$PROJECT_ROOT/output/app"/sportcam-app-*.tar.gz 2>/dev/null | head -1)
    fi

    log_info "Transferring: $APP_PKG"
    scp "$APP_PKG" "$DEVICE_USER@$DEVICE_IP:/tmp/"

    # 安装
    log_info "Installing on device..."
    ssh "$DEVICE_USER@$DEVICE_IP" << EOF
        cd /tmp
        tar xf $(basename "$APP_PKG")
        cd sportcam-app-*/
        ./install.sh
EOF

    log_info "Deployment complete!"
    log_info "Check app status: ssh $DEVICE_USER@$DEVICE_IP 'systemctl status sportcam'"
}

# 清理
clean_build() {
    log_info "Cleaning build artifacts..."
    rm -rf "$PROJECT_ROOT/build-simulator"
    rm -rf "$PROJECT_ROOT/build-target"
    rm -rf "$PROJECT_ROOT/output"
    log_info "Clean complete!"
}

# 执行命令
case $BUILD_TYPE in
    sim)
        build_simulator
        ;;
    cross)
        build_cross
        ;;
    app)
        build_app
        ;;
    system)
        log_info "Building system firmware..."
        "$SCRIPT_DIR/build_system.sh"
        ;;
    deploy)
        deploy_to_device
        ;;
    clean)
        clean_build
        ;;
    help)
        usage
        ;;
esac
```

