    62→void rkipc_get_opt(int argc, char *argv[]) {
    63→	for (;;) {
    64→		int idx;
    65→		int c;
    66→		c = getopt_long(argc, argv, short_options, long_options, &idx);
    67→		if (-1 == c)
    68→			break;
    69→		switch (c) {
    70→		case 0: /* getopt_long() flag */
    71→			break;
    72→		case 'c':
    73→			rkipc_ini_path_ = optarg;
    74→			break;
    75→		case 'a':
    76→			rkipc_iq_file_path_ = optarg;
    77→			break;
    78→		case 'l':
    79→			rkipc_log_level = atoi(optarg);
    80→			break;
    81→		case 'h':
    82→			usage_tip(stdout, argc, argv);
    83→			exit(EXIT_SUCCESS);
    84→		default:
    85→			usage_tip(stderr, argc, argv);
    86→			exit(EXIT_FAILURE);
    87→		}
    88→	}
