   100→static int find_adc_keys_device() {
   101→    for (int x = 0; x <= 10; x++) {
   102→        char path[64];
   103→        snprintf(path, sizeof(path), "/sys/class/input/event%d/device/name", x);
   104→
   105→        FILE *file = fopen(path, "r");
   106→        if (!file) continue;
   107→
   108→        char name[64];
   109→        if (fgets(name, sizeof(name), file)) {
   110→            name[strcspn(name, "\n")] = '\0';
   111→
   112→            if (strcmp(name, TARGET_DEVICE) == 0) {
   113→                fclose(file);
   114→                return x;
   115→            }
   116→        }
   117→        fclose(file);
   118→    }
   119→    return -1;
   120→}
