   122→#define AO_FREAD_SIZE 1024
   123→static void *wait_key_event(void *arg) {
   124→	int ret;
   125→	int key_fd;
   126→	char path[32];
   127→	int event_num = find_adc_keys_device();
   128→	if (event_num != -1) {
   129→		printf("Found %s at event%d\n", TARGET_DEVICE, event_num);
   130→	} else {
   131→		printf("Device %s not found\n", TARGET_DEVICE);
   132→		return NULL;
   133→	}
   134→	snprintf(path, sizeof(path), "/dev/input/event%d", event_num);
   135→	key_fd = open(path, O_RDONLY);
   136→	if (key_fd < 0) {
   137→		LOG_ERROR("can't open %s\n", path);
   138→		return NULL;
   139→	}
   140→	fd_set rfds;
   141→	int nfds = key_fd + 1;
   142→	struct timeval timeout;
   143→	struct input_event key_event;
   144→
   145→	while (g_main_run_) {
   146→		// The rfds collection must be emptied every time,
   147→		// otherwise the descriptor changes cannot be detected
   148→		memset(&timeout, 0, sizeof(timeout));
   149→		timeout.tv_sec = 1;
   150→		FD_ZERO(&rfds);
   151→		FD_SET(key_fd, &rfds);
   152→		ret = select(nfds, &rfds, NULL, NULL, &timeout);
   153→		if (ret < 0) {
   154→			LOG_ERROR("select failed : %s\n", strerror(errno));
   155→			continue;
   156→		}
   157→		if (ret == 0)
   158→			continue;
   159→		// wait for the key event to occur
   160→		if (FD_ISSET(key_fd, &rfds)) {
   161→			read(key_fd, &key_event, sizeof(key_event));
   162→			LOG_INFO("[timeval:sec:%ld,usec:%ld,type:%d,code:%d,value:%d]\n",
   163→			         key_event.input_event_sec, key_event.input_event_usec, key_event.type,
   164→			         key_event.code, key_event.value);
   165→			if ((key_event.code == KEY_LEFT) && key_event.value) {
   166→				LOG_INFO("get KEY_LEFT\n");
   167→				rkipc_ao_init();
   168→				FILE *fp = fopen("/oem/usr/share/speaker_test.wav", "rb");
   169→				int size = AO_FREAD_SIZE;
   170→				char *tmp_data;
   171→				tmp_data = malloc(AO_FREAD_SIZE);
   172→				while (size > 0) {
   173→					memset((void *)tmp_data, 0, AO_FREAD_SIZE);
   174→					size = fread(tmp_data, 1, AO_FREAD_SIZE, fp);
   175→					rkipc_ao_write(tmp_data, size);
   176→				}
   177→				rkipc_ao_write(tmp_data, 0);
   178→				free(tmp_data);
   179→				fclose(fp);
   180→				rkipc_ao_deinit();
   181→			}
   182→
   183→			if ((key_event.code == KEY_VOLUMEUP) && key_event.value) {
   184→				LOG_INFO("get KEY_VOLUMEUP\n");
   185→			}
   186→		}
   187→	}
   188→
   189→	if (key_fd) {
   190→		close(key_fd);
   191→		key_fd = 0;
   192→	}
   193→	LOG_DEBUG("wait key event out\n");
   194→	return NULL;
   195→}
