   411→static bool check_rk730_sound_card(void) {
   412→	FILE *fp;
   413→	char line[256];
   414→	bool found = false;
   415→
   416→	fp = fopen("/proc/asound/cards", "r");
   417→	if (fp == NULL) {
   418→		printf("Failed to open /proc/asound/cards\n");
   419→		return false;
   420→	}
   421→
   422→	while (fgets(line, sizeof(line), fp)) {
   423→		if (strstr(line, "rk730") != NULL) {
   424→			found = true;
   425→			break;
   426→		}
   427→	}
   428→
   429→	fclose(fp);
   430→	return found;
   431→}
