   433→int rkipc_ao_init_ex(int sample_rate, int channels, int frame_size) {
   434→	int ret = 0;
   435→	const char *card_name = rk_param_get_string("audio.0:card_name", "default");
   436→	AUDIO_DEV aoDevId = 0;
   437→	AO_CHN aoChn = 0;
   438→	AIO_ATTR_S aoAttr;
   439→	AO_CHN_PARAM_S pstParams;
   440→
   441→	memset(&pstParams, 0, sizeof(AO_CHN_PARAM_S));
   442→	memset(&aoAttr, 0, sizeof(AIO_ATTR_S));
   443→	sprintf((char *)aoAttr.u8CardName, "%s", card_name);
   444→
   445→	aoAttr.soundCard.channels = 2;
   446→	aoAttr.soundCard.sampleRate = sample_rate;
   447→	const char *format = rk_param_get_string("audio.0:format", NULL);
   448→	if (!strcmp(format, "S16")) {
   449→		aoAttr.soundCard.bitWidth = AUDIO_BIT_WIDTH_16;
   450→		aoAttr.enBitwidth = AUDIO_BIT_WIDTH_16;
   451→	} else if (!strcmp(format, "U8")) {
   452→		aoAttr.soundCard.bitWidth = AUDIO_BIT_WIDTH_8;
   453→		aoAttr.enBitwidth = AUDIO_BIT_WIDTH_8;
   454→	} else {
   455→		LOG_ERROR("not support %s\n", format);
   456→		return RK_FAILURE;
   457→	}
   458→	aoAttr.enSamplerate = (AUDIO_SAMPLE_RATE_E)sample_rate;
   459→
   460→	if (channels == 1)
   461→		aoAttr.enSoundmode = AUDIO_SOUND_MODE_MONO;
   462→	else if (channels == 2)
   463→		aoAttr.enSoundmode = AUDIO_SOUND_MODE_STEREO;
   464→	else {
   465→		LOG_ERROR("unsupport = %d\n", channels);
   466→		return RK_FAILURE;
   467→	}
   468→	aoAttr.u32PtNumPerFrm = frame_size;
   469→	aoAttr.u32FrmNum = 4;
   470→	aoAttr.u32EXFlag = 0;
   471→	aoAttr.u32ChnCnt = 2;
   472→
   473→	if (check_rk730_sound_card()) {
   474→		ret = RK_MPI_AMIX_SetControl(aoDevId, "spk switch", (char *)"on");
   475→		ret |= RK_MPI_AMIX_SetControl(aoDevId, "hp switch", (char *)"on");
   476→		ret |= RK_MPI_AMIX_SetControl(aoDevId, "OUT1 Switch", (char *)"on");
   477→		ret |= RK_MPI_AMIX_SetControl(aoDevId, "OUT2 Switch", (char *)"on");
   478→		if (ret != RK_SUCCESS) {
   479→			LOG_ERROR("RK_MPI_AMIX_SetControl failed %#X\n", ret);
   480→			return RK_FAILURE;
   481→		}
   482→	}
   483→	RK_MPI_AO_SetPubAttr(aoDevId, &aoAttr);
   484→	ret = RK_MPI_AO_Enable(aoDevId);
   485→	if (ret != RK_SUCCESS) {
   486→		LOG_ERROR("RK_MPI_AO_Enable failed %#X\n", ret);
   487→		return RK_FAILURE;
   488→	}
   489→	/*==============================================================================*/
   490→	pstParams.enLoopbackMode = AUDIO_LOOPBACK_NONE;
   491→	ret = RK_MPI_AO_SetChnParams(aoDevId, aoChn, &pstParams);
   492→	if (ret != RK_SUCCESS) {
   493→		LOG_ERROR("ao set channel params, aoChn = %d", aoChn);
   494→		return RK_FAILURE;
   495→	}
   496→
   497→	if (channels == 1)
   498→		RK_MPI_AO_SetTrackMode(aoDevId, AUDIO_TRACK_OUT_STEREO);
   499→	else
   500→		RK_MPI_AO_SetTrackMode(aoDevId, AUDIO_TRACK_NORMAL);
   501→	if (rk_param_get_int("audio.0:enable_ao_vqe", 0)) {
   502→		const char *vqe_file_path = rk_param_get_string("audio.0:ao_vqe_file", NULL);
   503→		if (vqe_file_path) {
   504→			AO_VQE_CONFIG_S vqe_config = {};
   505→			strncpy(vqe_config.aCfgFile, vqe_file_path, strlen(vqe_file_path));
   506→			vqe_config.enCfgMode = AIO_VQE_CONFIG_LOAD_FILE;
   507→			ret = RK_MPI_AO_SetVqeAttr(aoDevId, aoChn, &vqe_config);
   508→			if (ret != RK_SUCCESS) {
   509→				LOG_ERROR("RK_MPI_AO_SetVqeAttr failed %#X\n", ret);
   510→				return RK_FAILURE;
   511→			}
   512→			ret = RK_MPI_AO_EnableVqe(aoDevId, aoChn);
   513→			if (ret != RK_SUCCESS) {
   514→				LOG_ERROR("RK_MPI_AO_EnableVqe failed %#X\n", ret);
   515→				return RK_FAILURE;
   516→			}
   517→		}
   518→	}
   519→	/*==============================================================================*/
   520→	ret = RK_MPI_AO_EnableChn(aoDevId, aoChn);
   521→	if (ret != 0) {
   522→		LOG_ERROR("ao enable channel fail, aoChn = %d, reason = %x", aoChn, ret);
   523→		return RK_FAILURE;
   524→	}
   525→	/*==============================================================================*/
   526→	// set sample rate of input data
   527→	ret = RK_MPI_AO_EnableReSmp(aoDevId, aoChn, (AUDIO_SAMPLE_RATE_E)sample_rate);
   528→	if (ret != 0) {
   529→		LOG_ERROR("ao enable channel fail, reason = %x, aoChn = %d", ret, aoChn);
   530→		return RK_FAILURE;
   531→	}
   532→
   533→	ret = RK_MPI_AO_SetVolume(aoDevId, rk_param_get_int("audio.0:ao_volume", 100));
   534→	if (ret != 0) {
   535→		LOG_ERROR("RK_MPI_AO_SetVolume failed %#X\n", ret);
   536→		return RK_FAILURE;
   537→	}
   538→	LOG_INFO("create ao success\n");
   539→
   540→	return RK_SUCCESS;
   541→}
