   164→static int rkipc_storage_create_folder(char *folder) {
   165→	int i, len;
   166→
   167→	RKIPC_CHECK_POINTER(folder, RKIPC_STORAGE_FAIL);
   168→	len = strlen(folder);
   169→	if (!len) {
   170→		LOG_ERROR("Invalid path.\n");
   171→		return -1;
   172→	}
   173→	pthread_mutex_lock(&g_mkdir_mutex);
   174→	for (i = 1; i < len; i++) {
   175→		if (folder[i] != '/')
   176→			continue;
   177→		folder[i] = 0;
   178→		if (access(folder, R_OK)) {
   179→			if (mkdir(folder, 0755)) {
   180→				LOG_ERROR("mkdir error\n");
   181→				pthread_mutex_unlock(&g_mkdir_mutex);
   182→				return -1;
   183→			}
   184→		}
   185→		folder[i] = '/';
   186→	}
   187→	if (access(folder, R_OK)) {
   188→		if (mkdir(folder, 0755)) {
   189→			LOG_ERROR("mkdir error\n");
   190→			pthread_mutex_unlock(&g_mkdir_mutex);
   191→			return -1;
   192→		}
   193→	}
   194→	pthread_mutex_unlock(&g_mkdir_mutex);
   195→	LOG_DEBUG("Create %s finished\n", folder);
   196→
   197→	return 0;
   198→}
