   200→static int rkipc_storage_read_timeout(int fd, unsigned int u32WaitMs) {
   201→	int ret = 0;
   202→
   203→	if (u32WaitMs > 0) {
   204→		fd_set readFdset;
   205→		struct timeval timeout;
   206→
   207→		FD_ZERO(&readFdset);
   208→		FD_SET(fd, &readFdset);
   209→
   210→		timeout.tv_sec = u32WaitMs / 1000;
   211→		timeout.tv_usec = (u32WaitMs % 1000) * 1000;
   212→
   213→		do {
   214→			ret = select(fd + 1, &readFdset, NULL, NULL, &timeout);
   215→		} while (ret < 0 && errno == EINTR);
   216→
   217→		if (ret == 0) {
   218→			ret = -1;
   219→			errno = ETIMEDOUT;
   220→		} else if (ret == 1) {
   221→			return 0;
   222→		}
   223→	}
   224→
   225→	return ret;
   226→}
