   228→static int rkipc_storage_get_disk_size(char *path, int *total_size, int *free_size) {
   229→	struct statfs diskInfo;
   230→
   231→	RKIPC_CHECK_POINTER(path, RKIPC_STORAGE_FAIL);
   232→	RKIPC_CHECK_POINTER(total_size, RKIPC_STORAGE_FAIL);
