   245→static int rkipc_storage_get_mount_path(char *dev, char *path, int path_len) {
   246→	int ret = -1;
   247→	FILE *fp;
   248→	char strLine[MAX_STRLINE_LEN];
   249→	char *tmp;
   250→
   251→	RKIPC_CHECK_POINTER(dev, RKIPC_STORAGE_FAIL);
   252→	RKIPC_CHECK_POINTER(path, RKIPC_STORAGE_FAIL);
   253→
   254→	if ((fp = fopen("/proc/mounts", "r")) == NULL) {
   255→		LOG_ERROR("Open file error!\n");
   256→		return -1;
   257→	}
   258→	// avoid mount not yet completed at this time
   259→	usleep(100 * 1000);
   260→	memset(path, 0, path_len);
   261→	while (!feof(fp)) {
   262→		fgets(strLine, MAX_STRLINE_LEN, fp);
   263→		tmp = strstr(strLine, dev);
   264→
   265→		if (tmp) {
   266→			int len;
