   268→			char *e = strstr(s, " ");
   269→			len = e - s;
   270→
   271→			if ((len > 0) && (len < path_len)) {
   272→				memcpy(path, s, len);
   273→				ret = 0;
   274→			} else {
   275→				LOG_ERROR("len[%d], path_len[%d]", len, path_len);
   276→				ret = -2;
   277→			}
   278→
   279→			goto exit;
   280→		}

