398	      </tr>
399	      <tr>
400	        <td class="net-name c-blue">FEPHY_RXN</td>
401	        <td>H1.7 → <b>R6.1</b> → R6.2=RD-</td>
402	        <td><span class="tag tag-ctrl">差分-</span></td>
