428	      <tr>
429	        <td class="net-name c-yellow">RD-</td>
430	        <td>R6.2 → <b>L1.8</b>（变压器Pin8） + D5.1 + D6.2</td>
431	        <td>经5.1Ω(R6)后进变压器，同时连ESD D5/D6</td>
432	      </tr>
433	    </table>
