447	      <tr>
448	        <td class="net-name c-green">TDA-</td>
449	        <td>L1.14 → <b>RJ1.2</b></td>
450	        <td>Pin 2</td>
451	        <td>100Ω差分，与TDA+等长</td>
452	      </tr>
453	      <tr>
454	        <td class="net-name c-green">TDB+</td>
455	        <td>L1.11 → <b>RJ1.3</b></td>
456	        <td>Pin 3</td>
457	        <td>100Ω差分，与TDB-等长</td>
458	      </tr>
459	      <tr>
