497	    <table>
498	      <tr><th>器件</th><th>阳极(Pin2)</th><th>阴极(Pin1)→GND</th><th>保护的网络</th></tr>
499	      <tr><td>D1</td><td>TD+ (L1.1)</td><td>GND</td><td>变压器一次侧TX+</td></tr>
500	      <tr><td>D2</td><td>TD+ / TD-</td><td>GND</td><td>TX差分对之间</td></tr>
501	      <tr><td>D3</td><td>TD-</td><td>GND</td><td>变压器一次侧TX-</td></tr>
502	      <tr><td>D4</td><td>RD+</td><td>GND</td><td>变压器一次侧RX+</td></tr>
503	      <tr><td>D5</td><td>RD+ / RD-</td><td>GND</td><td>RX差分对之间</td></tr>
504	      <tr><td>D6</td><td>RD-</td><td>GND</td><td>变压器一次侧RX-</td></tr>
505	      <tr><td>D7</td><td>LAN1_MCT1(L1.15)</td><td>GND</td><td>二次侧中心抽头1</td></tr>
506	      <tr><td>D8</td><td>LAN1_MCT2(L1.10)</td><td>GND</td><td>二次侧中心抽头2</td></tr>
507	    </table>
508	    <div class="note" style="margin-top:0;">
